package com.bank.refcode;

import java.util.*;
import java.util.logging.*;

public class RefCodeDemo {
    private static final Logger log = Logger.getLogger("RefCode");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> codes = new ArrayList<>(List.of(
            "UPI1234567", "TX1", "AB9", "NEFT00045", "IMPS77"
        ));
        RefCodeService service = new RefCodeService();
        List<String> asc = service.sortByLength(codes);
        log.info("Reference codes shortest-first:");
        asc.forEach(c -> log.info(() -> "  " + c + " (len " + c.length() + ")"));
    }
}

// ─── Would be in service/RefCodeService.java ───
class RefCodeService {
    // comparingInt(String::length): order by character count, no boxing.
    // tie-break with naturalOrder() so equal-length codes are alphabetical.
    List<String> sortByLength(List<String> codes) {
        return codes.stream()
            .sorted(Comparator.comparingInt(String::length)
                .thenComparing(Comparator.naturalOrder()))
            .toList();
    }
}
